typedef void *pMenuEntry;

void *operator new(unsigned int, unsigned int, const char *, int);

class MenuEntryIntEdit
{
	char data[32];

public:
	MenuEntryIntEdit(const char *, int *, int, int);
};

class Menu
{
	char data[32];

public:
	Menu(Menu *, int, pMenuEntry *);
};

class MenuEntry
{
	unsigned int flags;

public:
	MenuEntry() { flags = 3; }
	virtual ~MenuEntry();
};

class MenuEntryLabel : public MenuEntry
{
protected:
	const char *label;

public:
	MenuEntryLabel(const char *t) { label = t; }
	virtual ~MenuEntryLabel();
};

class Submenu : public MenuEntryLabel
{
	Menu *menuopen;
	Menu *parent;
	void *system;

public:
	Submenu(char *text, Menu *p) : MenuEntryLabel(text) { menuopen=p; parent=0; system=0; }
	virtual ~Submenu();
};

struct WaverenderDebugStruct
{
	int DrawPassDark;
	int DrawPassFoam;
	int DrawPassHighCore;
	int DrawPassHighSpot;
	int DrawPassLight;
	int DrawPassTrans;
};

extern WaverenderDebugStruct WaverenderDebug;
extern MenuEntryIntEdit *WAVERENDER_MenuEntryDrawPassDark;
extern MenuEntryIntEdit *WAVERENDER_MenuEntryDrawPassFoam;
extern MenuEntryIntEdit *WAVERENDER_MenuEntryDrawPassHighCore;
extern MenuEntryIntEdit *WAVERENDER_MenuEntryDrawPassHighSpot;
extern MenuEntryIntEdit *WAVERENDER_MenuEntryDrawPassLight;
extern MenuEntryIntEdit *WAVERENDER_MenuEntryDrawPassTrans;
extern pMenuEntry WAVERENDER_MenuEntries[6];
extern Menu *waverender_menu;
extern Submenu *menu_waverender;

#define NEW new(0, "ks/waverendermenu.cpp", 0)
#define countof(x) (sizeof(x) / sizeof((x)[0]))

void WAVERENDER_StaticInit( void )
{
	int index = 0;
	WAVERENDER_MenuEntryDrawPassDark =
		NEW MenuEntryIntEdit("DrawPassDark", &WaverenderDebug.DrawPassDark, 0, 1);
	WAVERENDER_MenuEntryDrawPassFoam =
		NEW MenuEntryIntEdit("DrawPassFoam", &WaverenderDebug.DrawPassFoam, 0, 1);
	WAVERENDER_MenuEntryDrawPassHighCore =
		NEW MenuEntryIntEdit("DrawPassHighCore", &WaverenderDebug.DrawPassHighCore, 0, 1);
	WAVERENDER_MenuEntryDrawPassHighSpot =
		NEW MenuEntryIntEdit("DrawPassHighSpot", &WaverenderDebug.DrawPassHighSpot, 0, 1);
	WAVERENDER_MenuEntryDrawPassLight =
		NEW MenuEntryIntEdit("DrawPassLight", &WaverenderDebug.DrawPassLight, 0, 1);
	WAVERENDER_MenuEntryDrawPassTrans =
		NEW MenuEntryIntEdit("DrawPassTrans", &WaverenderDebug.DrawPassTrans, 0, 1);

	WAVERENDER_MenuEntries[index++] = WAVERENDER_MenuEntryDrawPassDark;
	WAVERENDER_MenuEntries[index++] = WAVERENDER_MenuEntryDrawPassFoam;
	WAVERENDER_MenuEntries[index++] = WAVERENDER_MenuEntryDrawPassHighCore;
	WAVERENDER_MenuEntries[index++] = WAVERENDER_MenuEntryDrawPassHighSpot;
	WAVERENDER_MenuEntries[index++] = WAVERENDER_MenuEntryDrawPassLight;
	WAVERENDER_MenuEntries[index++] = WAVERENDER_MenuEntryDrawPassTrans;

	waverender_menu = NEW Menu(NULL, countof(WAVERENDER_MenuEntries), WAVERENDER_MenuEntries);

	menu_waverender = NEW Submenu( "Wave Render Menu", waverender_menu );
}
